"model": "Eigen prijs: −0,2 × 10% = −2% (1). Kruislings: +0,3 × −10% = −3% (1). Bezetting 109 × 0,98 × 0,97 ≈ 103,62 of 109 × 0,95 = 103,55 (1).",
"pnt": 3,
